/* jQuery SidebarNav Bootstrap - simplified stable version */
!function($){
    "use strict";

    $.fn.SidebarNav = function(options){
        var settings = $.extend({
            animationSpeed: 300
        }, options);

        return this.each(function(){
            var $root = $(this);

            $root.on("click", "li a", function(e){
                var $link = $(this);
                var $submenu = $link.next("ul");

                if (!$submenu.length) {
                    return;
                }

                e.preventDefault();

                if ($submenu.is(":visible")) {
                    $submenu.slideUp(settings.animationSpeed, function(){
                        $submenu.removeClass("menu-open");
                    });
                    $submenu.parent("li").removeClass("active");
                    return;
                }

                var $parentList = $link.parents("ul").first();
                var $openMenus = $parentList.find("ul:visible");
                $openMenus.slideUp(settings.animationSpeed).removeClass("menu-open");
                $openMenus.parent("li").removeClass("active");

                $submenu.slideDown(settings.animationSpeed, function(){
                    $submenu.addClass("menu-open");
                    $submenu.parent("li").addClass("active");
                });
            });
        });
    };
}(jQuery);
